package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaIdDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sajdah_tilawah" to DuaText("Sajdah Bacaan", "Wajahku bersujud kepada Dzat yang menciptakannya dan memunculkan pendengaran dan penglihatannya dengan keperkasaan dan kekuasaan-Nya.", "Dalam sujud bacaannya.", "Nabi ﷺ mengatakan hal ini ketika sujud bacaannya di malam hari."),
        "dua_after_witr" to DuaText("Setelah Witr", "Maha Suci Raja Yang Maha Suci.", "Tiga kali setelah salam witir, ketiga kalinya meninggikan suara.", "Nabi ﷺ mengatakan hal ini setelah witir."),
        "dua_tahajjud_nur" to DuaText("Doa Pembukaan Tahajjud", "Ya Allah, milik-Mulah segala puji; Engkaulah yang memelihara langit, bumi dan seluruh isinya. Pujian milik-Mu; Engkaulah Cahaya langit, bumi dan segala yang ada di dalamnya. Pujian milik-Mu; Engkaulah Kebenaran, Janji-Mu benar, pertemuan dengan-Mu benar, Firman-Mu benar, Surga itu benar, Neraka itu benar, Para Nabi itu benar, Muhammad ﷺ itu benar, dan Hari Kiamat itu benar.", "Saat memulai shalat malam (tahajjud) (bagian pembuka doa).", "Nabi ﷺ membacakan ini tentang bangun untuk tahajud (doa selengkapnya ada di al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Bimbing Aku dalam Masalah yang Disengketakan", "Ya Allah, Rabb Jibril, Mika'il dan Israfil, Pencipta langit dan bumi, Yang Mengetahui yang gaib dan yang terlihat! Engkau akan menilai hamba-hamba-Mu berdasarkan perbedaan pendapat mereka. Bimbinglah aku dengan izin-Mu pada kebenaran dalam apa yang selama ini berbeda. Sesungguhnya Engkau memberi petunjuk kepada siapa saja yang Engkau kehendaki ke jalan yang lurus.", "Pada awal tahajud — untuk petunjuk kebenaran di tengah perselisihan.", "Nabi ﷺ memulai shalat malamnya dengan doa ini."),
        "dua_going_to_mosque_nur" to DuaText("Pergi ke Masjid (Doa Cahaya)", "Ya Allah, jadikanlah cahaya di hatiku, cahaya di mataku, cahaya di telingaku, cahaya di sebelah kananku, cahaya di sebelah kiriku, cahaya di atasku, cahaya di bawahku, cahaya di depanku, cahaya di belakangku, dan jadikanlah cahaya untukku.", "Saat pergi ke masjid untuk Subuh.", "Nabi ﷺ membacakan ini ketika keluar untuk shalat."),
        "dua_waswasa_salah" to DuaText("Waswasa Saat Sholat (Khinzab)", "Aku berlindung kepada Allah dari setan yang terlaknat.", "Ketika bisikan setan datang saat salat, carilah perlindungan dan keringkan ludah ke kiri sebanyak tiga kali.", "Utsman bin Abil-'As (RA) melakukan hal ini dan bisikan pun hilang."),
        "dua_alimal_ghayb" to DuaText("Yang Mengetahui Yang Gaib", "Ya Allah, Yang Mengetahui yang gaib dan yang terlihat, Pencipta langit dan bumi, Tuhan dan Penguasa segala sesuatu! Aku bersaksi bahwa tidak ada Tuhan selain Engkau. Aku berlindung kepada-Mu dari keburukan diriku sendiri, dan dari keburukan setan serta seruan kesyirikannya.", "Pagi, sore dan sebelum tidur — Nabi ﷺ mengajarkannya kepada Abu Bakar (RA).", "Perlindungan dari kejahatan diri dan setan."),
        "dua_fitratil_islam" to DuaText("Atas Fitrah Islam", "Telah kita masuki pagi hari atas fitrah Islam, atas ucapan keikhlasan, atas agama Nabi kita Muhammad ﷺ dan atas jalan ayah kita Ibrahim (AS) yang lurus dan muslim serta tidak termasuk orang-orang musyrik.", "Di pagi hari.", "Memperbarui iman seseorang setiap pagi."),
        "dua_amsayna_fitrah" to DuaText("Sore menjelang Fitrah Islam", "Telah kita masuki malam dengan fitrah Islam, dengan kata-kata keikhlasan, dengan agama Nabi kita Muhammad ﷺ dan dengan jalan ayah kita Ibrahim (AS), yang lurus dan muslim, dan tidak termasuk orang-orang musyrik.", "Di malam hari.", "Memperbarui iman seseorang setiap malam."),
        "dua_tahleel_10_fajr" to DuaText("Sepuluh Tahlil Setelah Subuh dan Maghrib", "Tidak ada yang berhak disembah kecuali Allah, sendiri, tanpa sekutu. Milik-Nya kekuasaan dan milik-Nya pujian; Dialah yang menghidupkan dan mematikan, dan Dia Maha Kuasa atas segala sesuatu.", "Sepuluh kali setelah Subuh (dan Maghrib), sebelum beranjak dari duduk atau berbicara.", "Sepuluh amal shaleh, sepuluh dosa terhapus, sepuluh derajat diangkat, dan perlindungan dari setan sepanjang hari."),
        "dua_la_hawla_kanz" to DuaText("Harta Karun Jannah", "Tidak ada daya dan kekuatan kecuali dengan izin Allah.", "Seringkali, setiap saat.", "Ini adalah salah satu harta surga."),
        "dua_four_beloved_words" to DuaText("Empat Kata Yang Paling Dicintai", "Maha Suci Allah, segala puji bagi Allah, tidak ada yang berhak disembah kecuali Allah, dan Allah Maha Besar.", "Kata-kata yang paling dicintai Allah.", "Mereka lebih disukai Nabi ﷺ dari segala sesuatu yang disinari matahari."),
        "dua_two_light_words" to DuaText("Dua Kata Ringan di Lidah", "Maha Suci Allah dan segala puji bagi-Nya; Alhamdulillah, Maha Besar.", "Ringan di lidah, berat di timbangan.", "Kekasih Yang Maha Penyayang, ringan di lidah dan berat di timbangan. (Hadits terakhir al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "Wahai Pemilik Keagungan dan Kehormatan!", "Peganglah itu dalam doa — petunjuk Nabi ﷺ.", "Nabi ﷺ bersabda: berpeganglah pada 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("Atas Namamu Aku Berbaring", "Dengan namaMu ya Tuhanku, aku berbaring miring dan dengan namaMu aku bangkit. Jika Engkau mengambil ruhku, kasihanilah, dan jika Engkau lepaskan, lindungilah seperti Engkau melindungi hamba-hamba-Mu yang shaleh.", "Setelah membersihkan tempat tidur dan berbaring.", "Mempercayakan jiwa seseorang kepada Allah sebelum tidur."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Kamu Menciptakan Jiwaku", "Ya Allah, Engkau menciptakan jiwaku dan Engkau akan mengambilnya. Kematian dan kehidupannya adalah milik-Mu. Jika Engkau memeliharanya tetap hidup, peliharalah, dan jika Engkau matikan, ampunilah. Ya Allah, aku mohon kesejahteraan pada-Mu.", "Sebelum tidur — riwayat Ibnu Umar (RA).", "Nabi ﷺ memerintahkan mengatakan hal ini sebelum tidur."),
        "dua_sleep_atamana" to DuaText("Syukur Sebelum Tidur", "Segala puji bagi Allah yang telah memberi kami makan, memberi kami minuman, mencukupi kebutuhan kami, dan memberi kami tempat berlindung. Berapa banyak orang yang tidak memiliki seorang pun yang mencukupi atau memberi mereka perlindungan.", "Saat hendak tidur.", "Nabi ﷺ mengatakan hal ini ketika hendak tidur."),
        "dua_sleep_rabbas_samawat" to DuaText("Penguasa Surga — Bayar Hutang Kami", "Ya Allah, Tuhan langit, bumi dan Arsy Yang Maha Perkasa, Tuhan kami dan Tuhan segala sesuatu, Pemecah biji dan batu kurma, Pengungkap Taurat, Injil dan Furqan! Aku berlindung kepada-Mu dari keburukan segala sesuatu yang ubun-ubunnya Engkau pegang. Ya Allah, Engkaulah Yang Pertama, tidak ada apa pun sebelum Engkau; Engkaulah Yang Terakhir, tidak ada apa pun setelah Engkau; Anda adalah Yang Terwujud, tidak ada apa pun di atas Anda; Engkaulah yang Tersembunyi, tidak ada sesuatu pun yang tersembunyi dari-Mu. Lunasi hutang kami dan bebaskan kami dari kemiskinan.", "Sebelum tidur, berbaring miring ke kanan — diajarkan kepada Fatimah (RA).", "Doa untuk terbebas dari hutang dan kesulitan."),
        "dua_sleep_fear" to DuaText("Ketakutan atau Kegelisahan dalam Tidur", "Aku berlindung dengan kalimat Allah yang sempurna dari murka-Nya dan siksa-Nya, dari kejahatan hamba-hamba-Nya, dan dari bisikan setan serta kedatangan mereka kepadaku.", "Saat merasa takut atau tidak nyaman dalam tidur.", "Dengan melakukan itu, hal itu tidak akan merugikannya."),
        "dua_waking_afani" to DuaText("Bangun: Dia Memulihkan Jiwaku", "Segala puji bagi Allah yang telah memberikan kesembuhan badanku, mengembalikan ruhku kepadaku, dan memperkenankanku mengingat-Nya.", "Saat bangun tidur.", "Syukur untuk pagi yang baru."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah adalah Tuhanku", "Allah, Allah adalah Tuhanku; Aku tidak mempersekutukan apapun dengan-Nya.", "Dalam kesedihan atau kesusahan — Nabi ﷺ mengajarkannya kepada Asma binti Umays (RA).", "Memegang tauhid disaat kesusahan."),
        "dua_rahmataka_arju" to DuaText("Rahmat-Mu yang Kuharapkan", "Ya Allah, rahmat-Mu lah yang kuharapkan, maka jangan tinggalkan aku sendirian walau sekejap mata, dan luruskanlah segala urusanku. Tidak ada Tuhan selain Engkau.", "Doa orang yang kesusahan (Dakwah al-makrub).", "Nabi ﷺ menyebutnya doa orang yang kesusahan."),
        "dua_against_enemy_ahzab" to DuaText("Melawan Pasukan Musuh", "Ya Allah, Pengungkap Kitab, Cepat dalam hisab! Kalahkan konfederasi. Ya Allah, kalahkan mereka dan guncangkan mereka.", "Melawan musuh — doa Pertempuran Konfederasi.", "Doa Nabi ﷺ melawan musuh."),
        "dua_anta_adudi" to DuaText("Anda adalah Dukungan Saya", "Ya Allah, Engkaulah pendukungku dan penolongku. OlehMu aku berencana, olehMu aku maju, dan olehMu aku berjuang.", "Sebelum kontes atau tantangan besar.", "Nabi ﷺ mengatakan ini dalam pertempuran."),
        "dua_ikfinihim" to DuaText("Cukuplah Aku Melawan Mereka", "Ya Allah, cukupkanlah aku melawan mereka, sesuai kehendak-Mu.", "Melawan kejahatan para penindas — doa anak laki-laki dalam kisah Rakyat Parit.", "Allah menyelamatkan anak itu dari para penindas."),
        "dua_qadarullah" to DuaText("Ketika Sesuatu yang Buruk Terjadi", "Itu adalah ketetapan Allah, dan Dia melakukan apa yang Dia kehendaki.", "Ketika sesuatu yang tidak menyenangkan terjadi, alih-alih mengatakan 'seandainya saja'.", "'Seandainya saja' membuka pintu bagi Setan."),
        "dua_ala_kulli_hal" to DuaText("Pujian dalam Segala Situasi", "Segala puji bagi Allah dalam segala keadaan.", "Ketika sesuatu yang tidak disukai terjadi.", "Nabi ﷺ mengatakan hal ini ketika menghadapi sesuatu yang tidak disukainya."),
        "dua_dogs_barking" to DuaText("Mendengar Anjing Menggonggong di Malam Hari", "Aku berlindung kepada Allah dari setan yang terlaknat.", "Saat mendengar anjing menggonggong atau ringkikan keledai di malam hari.", "Mereka melihat apa yang tidak Anda lihat."),
        "dua_leaving_home_adilla" to DuaText("Berlindung dari Kesesatan", "Ya Allah, aku berlindung kepada-Mu agar aku tidak tersesat atau disesatkan, jangan sampai aku terpeleset atau dibuat terpeleset, jangan sampai aku berbuat zalim atau dizalimi, jangan sampai aku bertindak bodoh atau diperlakukan dengan bodoh.", "Saat keluar rumah — riwayat Ummu Salamah (RA).", "Nabi ﷺ membacakan ini setiap kali dia meninggalkan rumahnya."),
        "dua_ascending_descending" to DuaText("Naik dan Turun", "Allah Maha Besar (ketika naik). — Maha Suci Allah (ketika turun).", "Dalam perjalanan, ucapkan 'Allahu Akbar' saat naik dan 'SubhanAllah' saat turun.", "Amalan Para Sahabat (RA) Saat Berpergian."),
        "dua_traveller_sahar" to DuaText("Doa Wisatawan Sebelum Fajar", "Seorang pendengar telah mendengar (dan menyampaikan) puji-pujian kita kepada Allah dan nikmat-nikmat-Nya kepada kita. Ya Tuhan kami, temani kami dan limpahkanlah nikmat-Mu kepada kami - (saya katakan ini) mencari perlindungan kepada Allah dari api neraka.", "Dalam sebuah perjalanan, sebelum fajar.", "Nabi ﷺ mengatakan hal ini sebelum fajar ketika bepergian."),
        "dua_zawwadakallah" to DuaText("Kepada Wisatawan : Semoga Allah Memberikan Taqwa", "Semoga Allah memberikan ketaqwaan dalam perjalananmu, mengampuni dosa-dosamu dan memudahkan kebaikanmu dimanapun kamu berada.", "Saat mengucapkan selamat tinggal pada seorang musafir.", "Nabi ﷺ memberikan doa ini kepada seseorang yang sedang melakukan perjalanan."),
        "dua_traveller_to_resident" to DuaText("Pelancong ke Mereka yang Tinggal di Belakang", "Aku mempercayakanmu kepada Allah yang kepercayaannya tidak pernah hilang.", "Diucapkan traveler saat berpamitan dengan keluarga.", "Percayakan keselamatan keluarga kepada Allah."),
        "dua_entering_village" to DuaText("Memasuki Kota atau Desa", "Ya Allah, Rabb ketujuh langit dan segala yang dinaunginya, Rabb tujuh bumi dan segala yang dibawanya, Rabb setan-setan dan segala kesesatannya, Rabb angin dan segala yang disebarkannya! Kami memohon kepada-Mu kebaikan kota ini dan kebaikan penduduknya, dan kami memohon perlindungan kepada-Mu dari keburukan kota ini, keburukan penduduknya, dan kejahatan apa yang ada di dalamnya.", "Sebelum memasuki kota atau kota.", "Nabi ﷺ membacakan ini setiap kali dia ingin memasuki sebuah kota."),
        "dua_vehicle_stumbles" to DuaText("Saat Kendaraan Tersandung", "Dengan menyebut nama Allah.", "Apabila gunung atau kendaraan terpeleset atau tersandung, alih-alih mengucapkan 'Semoga Setan binasa'.", "Mengucapkan Bismillah membuat Setan mengecil hingga sebesar lalat."),
        "dua_ajz_kasal_haram" to DuaText("Berlindung dari Kelemahan dan Usia Tua", "Ya Allah, aku berlindung kepada-Mu dari ketidakberdayaan dan kemalasan, dari kepengecutan dan usia tua, dari cobaan hidup dan mati, dan dari siksa kubur.", "Doa perlindungan harian yang komprehensif.", "Doa yang sering diucapkan Nabi ﷺ."),
        "dua_sharri_ma_amiltu" to DuaText("Berlindung dari Kejahatan Perbuatanku", "Ya Allah, aku berlindung kepada-Mu dari keburukan apa yang telah kulakukan dan dari keburukan apa yang belum kulakukan.", "Doa Nabi ﷺ, menurut Aisha (RA).", "Perlindungan dari akibat baik yang telah dilakukan maupun yang tidak dilakukan."),
        "dua_jahdil_bala" to DuaText("Berlindung dari Cobaan Berat", "Ya Allah, aku berlindung kepada-Mu dari cobaan berat, dari kesengsaraan, dari keburukan, dan dari sombongnya musuh.", "Berlindung dari cobaan berat dan sombongnya musuh.", "Nabi ﷺ berlindung dari empat hal ini."),
        "dua_fitnat_ghina_faqr" to DuaText("Perlindungan dari Cobaan Kekayaan dan Kemiskinan", "Ya Allah, aku berlindung kepada-Mu dari kemalasan dan usia tua, dari dosa dan hutang, dari cobaan dan siksa kubur, dari cobaan dan siksa Neraka, dari keburukan cobaan harta, dan dari cobaan kemiskinan.", "Perlindungan dari cobaan kubur, Neraka, kekayaan dan kemiskinan (bagian dari doa).", "Doa perlindungan yang komprehensif dari Nabi ﷺ."),
        "dua_kufr_faqr" to DuaText("Perlindungan dari Ketidakpercayaan dan Kemiskinan", "Ya Allah, aku berlindung kepada-Mu dari kekafiran dan kemiskinan, dan aku berlindung kepada-Mu dari siksa kubur. Tidak ada Tuhan selain Engkau.", "Tiga kali pagi dan sore.", "Abu Bakar (RA) mendengar Nabi ﷺ mengatakan ini."),
    )
}
